script:
files = []
def walk(path):
    for name in repo.list(path):
        p = path + "/" + name if path != "." else name
        if name.endswith("/"):
            walk(p)
        else:
            files.append(p)

walk("src")
result({
  "files": files,
  "contents": {p: repo.read(p) for p in files},
  "docs": repo.read("docs/history.txt"),
})

result({
  "all_oldclient_any_case": [(h.path, h.line, h.text.strip()[:120]) for h in repo.search("(?i)oldclient")],
  "src_newclient": [(h.path, h.line, h.text.strip()[:120]) for h in repo.search("NewClient")],
})

